package com.liam.rankladder;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class RankLadderClientTest
{
	// row shape captured from a live ironman Vet'ion page (2026-07-20)
	private static final String PAGE_EXCERPT =
		"<table>\n"
			+ "<tr class=\"personal-hiscores__row\">\n"
			+ "  <td class=\"right\">69</td>\n"
			+ "  <td class=\"left\"> <a href=\"hiscorepersonal?user1=Nooters\">Nooters</a></td>\n"
			+ "  <td class=\"right\">2,716</td>\n"
			+ "</tr>\n"
			+ "<tr class=\"personal-hiscores__row\"><td class=\"right\">1,070</td>"
			+ "<td class=\"left\"><a href=\"hiscorepersonal?user1=Ka+ll+e\">Ka ll e</a></td>"
			+ "<td class=\"right\">1,234,567</td></tr>\n"
			+ "</table>";

	@Test
	public void parsesRowsWithCommasWhitespaceAndNbsp()
	{
		List<RankLadderState.LadderEntry> rows = RankLadderClient.parseLadderRows(PAGE_EXCERPT);
		assertEquals(2, rows.size());
		assertEquals(69, rows.get(0).getRank());
		assertEquals("Nooters", rows.get(0).getName());
		assertEquals(2_716, rows.get(0).getScore());
		assertEquals(1_070, rows.get(1).getRank());
		assertEquals("Ka ll e", rows.get(1).getName());
		assertEquals(1_234_567, rows.get(1).getScore());
	}

	@Test
	public void ignoresNonRowMarkup()
	{
		assertEquals(0, RankLadderClient.parseLadderRows("<html><body>No rows here</body></html>").size());
	}
}

