package com.liam.rankladder;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import lombok.Value;

/**
 * Current ladder snapshot plus rank/score history for rate and ETA
 * estimates. Written from the polling executor, read on the EDT; the
 * ladder list is replaced wholesale, never mutated in place.
 */
@Singleton
@Getter
@Setter
public class RankLadderState
{
	@Value
	public static class LadderEntry
	{
		int rank;
		String name;
		long score;
		boolean you;
	}

	/**
	 * Samples of (epochMs, rank, score) for the tracked player.
	 */
	@Value
	public static class RankSample
	{
		long timeMs;
		int rank;
		long score;
	}

	private volatile List<LadderEntry> ladder = new ArrayList<>();
	private volatile int yourRank;
	private volatile long yourScore;
	private volatile long lastUpdatedMs;
	private volatile String error;
	/**
	 * True when the error is a real failure (network trouble) rather
	 * than guidance like choosing an activity; the panel colors them
	 * differently.
	 */
	private volatile boolean errorFailure;

	private volatile RankLadderClient.HiscoreMode selectedMode = RankLadderClient.HiscoreMode.REGULAR;
	private volatile String selectedActivity = "";
	private volatile List<String> activityNames = new ArrayList<>();
	private volatile LadderEntry rankOne;
	private volatile int sessionStartRank;

	private final List<RankSample> history = new ArrayList<>();

	public synchronized void addSample(RankSample sample)
	{
		history.add(sample);
		if (history.size() > 5000)
		{
			history.remove(0);
		}
	}

	public synchronized void replaceHistory(List<RankSample> samples)
	{
		history.clear();
		history.addAll(samples);
	}

	public synchronized RankSample lastSample()
	{
		return history.isEmpty() ? null : history.get(history.size() - 1);
	}

	public synchronized List<RankSample> historyCopy()
	{
		return new ArrayList<>(history);
	}

	/**
	 * Average score gained per hour over the recent history window. The
	 * window extends to the latest successful poll, not just the latest
	 * change, so the pace decays honestly while nothing is gained. NaN
	 * means not enough data yet; 0 means genuinely no gain.
	 */
	public double scorePerHour()
	{
		List<RankSample> samples = historyCopy();
		long cutoff = System.currentTimeMillis() - 72 * 3_600_000L;
		RankSample first = null;
		RankSample last = null;
		for (RankSample sample : samples)
		{
			if (sample.getTimeMs() < cutoff)
			{
				continue;
			}
			if (first == null)
			{
				first = sample;
			}
			last = sample;
		}
		if (first == null || last == null)
		{
			return Double.NaN;
		}
		long end = Math.max(last.getTimeMs(), lastUpdatedMs);
		if (end - first.getTimeMs() < 15 * 60_000L)
		{
			return Double.NaN;
		}
		long delta = last.getScore() - first.getScore();
		if (delta <= 0)
		{
			return 0;
		}
		double hours = (end - first.getTimeMs()) / 3_600_000.0;
		return delta / hours;
	}

	/**
	 * Ranks climbed per day over the last week (positive = climbing),
	 * with the same to-latest-poll window end. NaN without enough data;
	 * 0 when holding steady.
	 */
	public double ranksPerDay()
	{
		List<RankSample> samples = historyCopy();
		long cutoff = System.currentTimeMillis() - 7 * 24 * 3_600_000L;
		RankSample first = null;
		RankSample last = null;
		for (RankSample sample : samples)
		{
			if (sample.getTimeMs() < cutoff)
			{
				continue;
			}
			if (first == null)
			{
				first = sample;
			}
			last = sample;
		}
		if (first == null || last == null)
		{
			return Double.NaN;
		}
		long end = Math.max(last.getTimeMs(), lastUpdatedMs);
		if (end - first.getTimeMs() < 3_600_000L)
		{
			return Double.NaN;
		}
		double days = (end - first.getTimeMs()) / 86_400_000.0;
		return (first.getRank() - last.getRank()) / days;
	}
}

package com.liam.rankladder;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches the official Jagex hiscores: the per-player JSON (which also
 * supplies the live activity list, since activity ids shift whenever
 * Jagex adds content) and the leaderboard pages around a rank. Blocking
 * IO; call from the polling executor only, never the client thread.
 * Endpoint shapes were verified against the live hiscores.
 */
@Singleton
public class RankLadderClient
{
	private static final String BASE = "https://secure.runescape.com/m=";
	private static final Pattern ROW = Pattern.compile(
		"personal-hiscores__row\">\\s*<td class=\"right\">\\s*([\\d,]+)\\s*</td>\\s*"
			+ "<td class=\"left\">\\s*<a[^>]*>([^<]+)</a>\\s*</td>\\s*"
			+ "<td class=\"right\">\\s*([\\d,]+)", Pattern.DOTALL);

	public static final int PAGE_SIZE = 25;

	/**
	 * The hiscore boards a ladder can be tracked on.
	 */
	public enum HiscoreMode
	{
		REGULAR("Regular", "hiscore_oldschool"),
		IRONMAN("Ironman", "hiscore_oldschool_ironman"),
		HARDCORE_IRONMAN("Hardcore Ironman", "hiscore_oldschool_hardcore_ironman"),
		ULTIMATE_IRONMAN("Ultimate Ironman", "hiscore_oldschool_ultimate"),
		DEADMAN("Deadman", "hiscore_oldschool_deadman"),
		LEAGUES("Leagues", "hiscore_oldschool_seasonal"),
		SKILLER("Skiller", "hiscore_oldschool_skiller"),
		ONE_DEFENCE("1 Defence", "hiscore_oldschool_skiller_defence"),
		FRESH_START("Fresh Start", "hiscore_oldschool_fresh_start");

		private final String displayName;
		private final String prefix;

		HiscoreMode(String displayName, String prefix)
		{
			this.displayName = displayName;
			this.prefix = prefix;
		}

		public String getPrefix()
		{
			return prefix;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * One activity from index_lite.json: the id doubles as the
	 * leaderboard table number, valid only for the fetch it came from.
	 */
	@Value
	public static class Activity
	{
		int id;
		String name;
		int rank;
		long score;
	}

	public static class PlayerResult
	{
		String name;
		List<Activity> activities;

		public String getName()
		{
			return name;
		}

		public List<Activity> getActivities()
		{
			return activities;
		}
	}

	/**
	 * Thrown for a name the hiscores do not know (HTTP 404).
	 */
	public static class PlayerNotFoundException extends IOException
	{
		PlayerNotFoundException(String name)
		{
			super("No hiscores entry for " + name);
		}
	}

	/**
	 * Thrown when a board serves an empty array instead of a player
	 * object (e.g. the Leagues endpoint between leagues).
	 */
	public static class EmptyBoardException extends IOException
	{
		EmptyBoardException()
		{
			super("Board has no data");
		}
	}

	private final OkHttpClient okHttpClient;
	private final Gson gson;

	@Inject
	private RankLadderClient(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	/**
	 * The player's full activity list (with their rank and score in
	 * each) on the given board.
	 */
	public PlayerResult fetchPlayer(HiscoreMode mode, String player) throws IOException
	{
		HttpUrl url = HttpUrl.parse(BASE + mode.getPrefix() + "/index_lite.json").newBuilder()
			.addQueryParameter("player", player)
			.build();
		try (Response response = okHttpClient.newCall(new Request.Builder().url(url).build()).execute())
		{
			if (response.code() == 404)
			{
				throw new PlayerNotFoundException(player);
			}
			if (!response.isSuccessful())
			{
				throw new IOException("Hiscores returned HTTP " + response.code());
			}
			String body = response.body().string();
			if (body.trim().startsWith("["))
			{
				// off-season boards serve [] with HTTP 200
				throw new EmptyBoardException();
			}
			PlayerResult result = gson.fromJson(body, PlayerResult.class);
			if (result == null || result.getActivities() == null)
			{
				throw new IOException("Unexpected hiscores response shape");
			}
			return result;
		}
	}

	/**
	 * One 25-row leaderboard page (1-indexed; rank r lives on page
	 * floor((r-1)/25)+1) for an activity table.
	 */
	public List<RankLadderState.LadderEntry> fetchLadderPage(HiscoreMode mode, int tableId, int page)
		throws IOException
	{
		HttpUrl url = HttpUrl.parse(BASE + mode.getPrefix() + "/overall.ws").newBuilder()
			.addQueryParameter("category_type", "1")
			.addQueryParameter("table", String.valueOf(tableId))
			.addQueryParameter("page", String.valueOf(page))
			.build();
		try (Response response = okHttpClient.newCall(new Request.Builder().url(url).build()).execute())
		{
			if (!response.isSuccessful())
			{
				throw new IOException("Hiscores returned HTTP " + response.code());
			}
			return parseLadderRows(response.body().string());
		}
	}

	static List<RankLadderState.LadderEntry> parseLadderRows(String html)
	{
		List<RankLadderState.LadderEntry> entries = new ArrayList<>();
		Matcher matcher = ROW.matcher(html);
		while (matcher.find())
		{
			entries.add(new RankLadderState.LadderEntry(
				(int) parseNumber(matcher.group(1)),
				cleanName(matcher.group(2)),
				parseNumber(matcher.group(3)),
				false));
		}
		return entries;
	}

	/**
	 * The current rank 1 row of an activity table, or null if the table
	 * is empty.
	 */
	public RankLadderState.LadderEntry fetchRankOne(HiscoreMode mode, int tableId) throws IOException
	{
		HttpUrl url = HttpUrl.parse(BASE + mode.getPrefix() + "/ranking.json").newBuilder()
			.addQueryParameter("table", String.valueOf(tableId))
			.addQueryParameter("category", "1")
			.addQueryParameter("size", "1")
			.build();
		try (Response response = okHttpClient.newCall(new Request.Builder().url(url).build()).execute())
		{
			if (!response.isSuccessful())
			{
				throw new IOException("Hiscores returned HTTP " + response.code());
			}
			TopEntry[] rows = gson.fromJson(response.body().string(), TopEntry[].class);
			if (rows == null || rows.length == 0 || rows[0] == null)
			{
				return null;
			}
			return new RankLadderState.LadderEntry(
				(int) parseNumber(rows[0].rank), cleanName(rows[0].name), parseNumber(rows[0].score), false);
		}
	}

	private static class TopEntry
	{
		String name;
		// rank and score arrive as strings with comma separators
		String rank;
		String score;
	}

	private static long parseNumber(String raw)
	{
		return Long.parseLong(raw.replace(",", "").trim());
	}

	private static String cleanName(String raw)
	{
		// leaderboard names can carry non-breaking spaces
		return raw.replace('\u00A0', ' ').trim();
	}
}

package com.liam.rankladder;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.RuneLite;

/**
 * Refreshes the ladder while the panel is open, on its own single
 * worker thread so slow hiscores responses never block RuneLite's
 * shared executor. Polls run under a generation counter: any stop,
 * restart or selection change bumps the generation, and an in-flight
 * poll whose generation is stale discards its results instead of
 * writing a previous board's data over the new one. History persists
 * per player/mode/activity under .runelite/noots-rank-ladder/ with
 * atomic file replacement.
 */
@Slf4j
@Singleton
public class RankLadderPoller
{
	private static final File DATA_DIR = new File(RuneLite.RUNELITE_DIR, "noots-rank-ladder");

	private final RankLadderClient ladderClient;
	private final RankLadderState state;
	private final RankLadderConfig config;
	private final Client client;
	private final Gson gson;

	private ScheduledExecutorService executor;
	private ScheduledFuture<?> pollFuture;
	private Runnable refreshCallback;
	private String loadedHistoryKey;
	private int generation;

	@Inject
	private RankLadderPoller(RankLadderClient ladderClient, RankLadderState state,
		RankLadderConfig config, Client client, Gson gson)
	{
		this.ladderClient = ladderClient;
		this.state = state;
		this.config = config;
		this.client = client;
		this.gson = gson;
	}

	synchronized void setRefreshCallback(Runnable callback)
	{
		refreshCallback = callback;
	}

	/**
	 * Begin periodic polling if not already running.
	 */
	synchronized void start()
	{
		if (pollFuture != null && !pollFuture.isCancelled())
		{
			return;
		}
		schedule();
	}

	/**
	 * Poll immediately and realign the periodic delay behind it
	 * (refresh button, selection change).
	 */
	synchronized void pollNow()
	{
		schedule();
	}

	synchronized void stop()
	{
		generation++;
		if (pollFuture != null)
		{
			log.debug("rank ladder polling stopped");
			pollFuture.cancel(false);
			pollFuture = null;
		}
	}

	/**
	 * Full teardown for plugin shutDown.
	 */
	synchronized void shutDown()
	{
		stop();
		refreshCallback = null;
		loadedHistoryKey = null;
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
	}

	private synchronized void schedule()
	{
		stop();
		if (executor == null || executor.isShutdown())
		{
			executor = Executors.newSingleThreadScheduledExecutor(runnable ->
			{
				Thread thread = new Thread(runnable, "noots-rank-ladder");
				thread.setDaemon(true);
				return thread;
			});
		}
		log.debug("rank ladder polling started (generation {})", generation);
		pollFuture = executor.scheduleWithFixedDelay(this::pollSafely, 0,
			Math.max(30, config.pollSeconds()), TimeUnit.SECONDS);
	}

	private void pollSafely()
	{
		int gen;
		synchronized (this)
		{
			gen = generation;
		}
		String status;
		boolean failure = false;
		try
		{
			status = poll(gen);
		}
		catch (RankLadderClient.PlayerNotFoundException e)
		{
			status = "Player not found on these hiscores";
		}
		catch (RankLadderClient.EmptyBoardException e)
		{
			status = "This board has no data right now";
		}
		catch (IOException e)
		{
			log.debug("hiscores poll failed", e);
			status = "Hiscores unavailable, retrying";
			failure = true;
		}
		catch (Exception e)
		{
			log.debug("unexpected poll failure", e);
			status = "Something went wrong, retrying";
			failure = true;
		}
		finishPoll(gen, status, failure);
	}

	/**
	 * @return a user-facing status message, or null for full success.
	 */
	private String poll(int gen) throws IOException
	{
		String player = trackedPlayer();
		if (player == null || player.isEmpty())
		{
			return "Log in or set a player name in the config";
		}
		// capture the selection once; the user may change it mid-poll
		RankLadderClient.HiscoreMode mode = state.getSelectedMode();
		String activityName = state.getSelectedActivity();
		log.debug("rank ladder poll: mode={} activity={}", mode, activityName);

		// one lookup gives the player's rank/score AND the live activity
		// list (ids shift when Jagex adds content, so never cache them)
		RankLadderClient.PlayerResult result = ladderClient.fetchPlayer(mode, player);
		List<String> names = new ArrayList<>();
		RankLadderClient.Activity selected = null;
		for (RankLadderClient.Activity activity : result.getActivities())
		{
			names.add(activity.getName());
			if (activity.getName().equals(activityName))
			{
				selected = activity;
			}
		}
		if (!commitActivityNames(gen, names))
		{
			return null;
		}
		if (selected == null)
		{
			commitLadder(gen, new ArrayList<>(), 0, 0, null);
			return activityName == null || activityName.isEmpty()
				? "Choose an activity to track"
				: "Unknown activity: " + activityName;
		}

		loadHistoryIfNeeded(gen, player, mode, selected.getName());

		if (selected.getRank() <= 0)
		{
			commitLadder(gen, new ArrayList<>(), -1, selected.getScore(), null);
			return "Not ranked in " + selected.getName() + " yet";
		}

		// fetch the pages covering the window around the tracked rank
		int depth = config.ladderDepth();
		Set<Integer> fetchedPages = new HashSet<>();
		List<RankLadderState.LadderEntry> rows = new ArrayList<>();
		fetchWindowPages(mode, selected.getId(), selected.getRank(), depth, fetchedPages, rows);

		// the leaderboard is live and can disagree with the player fetch;
		// trust the row bearing the player's name when it exists
		RankLadderState.LadderEntry live = findByName(rows, player);
		int anchorRank = live != null ? live.getRank() : selected.getRank();
		long anchorScore = live != null ? live.getScore() : selected.getScore();
		if (live != null && live.getRank() != selected.getRank())
		{
			log.debug("rank moved between fetches: {} -> {}", selected.getRank(), live.getRank());
			fetchWindowPages(mode, selected.getId(), anchorRank, depth, fetchedPages, rows);
		}

		int firstRank = Math.max(1, anchorRank - depth);
		int lastRank = anchorRank + depth;
		List<RankLadderState.LadderEntry> window = new ArrayList<>();
		for (RankLadderState.LadderEntry row : rows)
		{
			if (row.getRank() >= firstRank && row.getRank() <= lastRank)
			{
				window.add(new RankLadderState.LadderEntry(row.getRank(), row.getName(),
					row.getScore(), normalizeName(row.getName()).equalsIgnoreCase(normalizeName(player))));
			}
		}
		window.sort(java.util.Comparator.comparingInt(RankLadderState.LadderEntry::getRank));

		RankLadderState.LadderEntry rankOne = ladderClient.fetchRankOne(mode, selected.getId());

		if (commitLadder(gen, window, anchorRank, anchorScore, rankOne))
		{
			recordSample(player, mode, selected.getName(), anchorRank, anchorScore);
		}
		return null;
	}

	private void fetchWindowPages(RankLadderClient.HiscoreMode mode, int tableId, int aroundRank,
		int depth, Set<Integer> fetchedPages, List<RankLadderState.LadderEntry> rows) throws IOException
	{
		int firstPage = (Math.max(1, aroundRank - depth) - 1) / RankLadderClient.PAGE_SIZE + 1;
		int lastPage = (aroundRank + depth - 1) / RankLadderClient.PAGE_SIZE + 1;
		for (int page = firstPage; page <= lastPage; page++)
		{
			if (fetchedPages.add(page))
			{
				rows.addAll(ladderClient.fetchLadderPage(mode, tableId, page));
			}
		}
	}

	private RankLadderState.LadderEntry findByName(List<RankLadderState.LadderEntry> rows, String player)
	{
		String wanted = normalizeName(player);
		for (RankLadderState.LadderEntry row : rows)
		{
			if (normalizeName(row.getName()).equalsIgnoreCase(wanted))
			{
				return row;
			}
		}
		return null;
	}

	// ---- generation-guarded commits ----

	private synchronized boolean commitActivityNames(int gen, List<String> names)
	{
		if (gen != generation)
		{
			log.debug("discarding stale poll (generation moved)");
			return false;
		}
		state.setActivityNames(names);
		return true;
	}

	private synchronized boolean commitLadder(int gen, List<RankLadderState.LadderEntry> window,
		int rank, long score, RankLadderState.LadderEntry rankOne)
	{
		if (gen != generation)
		{
			log.debug("discarding stale poll (generation moved)");
			return false;
		}
		state.setLadder(window);
		state.setYourRank(rank);
		state.setYourScore(score);
		state.setRankOne(rankOne);
		if (rank > 0)
		{
			state.setLastUpdatedMs(System.currentTimeMillis());
			if (state.getSessionStartRank() == 0)
			{
				state.setSessionStartRank(rank);
			}
		}
		return true;
	}

	private void finishPoll(int gen, String status, boolean failure)
	{
		Runnable callback;
		synchronized (this)
		{
			if (gen != generation)
			{
				log.debug("discarding stale poll result (generation moved)");
				return;
			}
			state.setError(status);
			state.setErrorFailure(failure);
			callback = refreshCallback;
		}
		if (callback != null)
		{
			callback.run();
		}
	}

	private String trackedPlayer()
	{
		String configured = config.playerName().trim();
		if (!configured.isEmpty())
		{
			return configured;
		}
		Player local = client.getLocalPlayer();
		return local != null ? normalizeName(local.getName()) : null;
	}

	/**
	 * Local player names use non-breaking spaces (char 160); the
	 * leaderboard uses plain ones. Normalize before any comparison.
	 */
	private static String normalizeName(String name)
	{
		return name == null ? "" : name.replace((char) 160, ' ').trim();
	}

	// ---- history persistence ----

	private String historyKey(String player, RankLadderClient.HiscoreMode mode, String activity)
	{
		String raw = player + "|" + mode.name() + "|" + activity;
		// hash suffix keeps sanitized names from colliding
		return raw.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "_")
			+ "_" + Integer.toHexString(raw.toLowerCase(Locale.ROOT).hashCode());
	}

	private File historyFile(String key)
	{
		return new File(DATA_DIR, key + ".json");
	}

	private void loadHistoryIfNeeded(int gen, String player, RankLadderClient.HiscoreMode mode, String activity)
	{
		String key = historyKey(player, mode, activity);
		synchronized (this)
		{
			if (gen != generation || key.equals(loadedHistoryKey))
			{
				return;
			}
			loadedHistoryKey = key;
		}
		List<RankLadderState.RankSample> loaded = new ArrayList<>();
		File file = historyFile(key);
		if (file.exists())
		{
			try
			{
				String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
				List<RankLadderState.RankSample> parsed = gson.fromJson(json,
					new TypeToken<List<RankLadderState.RankSample>>()
					{
					}.getType());
				if (parsed != null)
				{
					loaded = parsed;
				}
			}
			catch (Exception e)
			{
				log.debug("could not read history {}", file, e);
			}
		}
		// commit under the same guard pattern as the ladder writes so a
		// stale thread cannot replace a newer selection's history
		synchronized (this)
		{
			if (gen != generation || !key.equals(loadedHistoryKey))
			{
				return;
			}
			state.setSessionStartRank(0);
			state.replaceHistory(loaded);
		}
	}

	private void recordSample(String player, RankLadderClient.HiscoreMode mode, String activity,
		int rank, long score)
	{
		RankLadderState.RankSample last = state.lastSample();
		if (last != null && last.getRank() == rank && last.getScore() == score)
		{
			return;
		}
		state.addSample(new RankLadderState.RankSample(System.currentTimeMillis(), rank, score));
		try
		{
			if (!DATA_DIR.exists() && !DATA_DIR.mkdirs())
			{
				log.debug("could not create {}", DATA_DIR);
				return;
			}
			File file = historyFile(historyKey(player, mode, activity));
			File temp = new File(DATA_DIR, file.getName() + ".tmp");
			Files.write(temp.toPath(),
				gson.toJson(state.historyCopy()).getBytes(StandardCharsets.UTF_8));
			try
			{
				Files.move(temp.toPath(), file.toPath(),
					StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				Files.move(temp.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException e)
		{
			log.debug("could not persist history", e);
		}
	}
}

package com.liam.rankladder;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Provider;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

/**
 * Live hiscore rank ladder: shows the players ranked just above and below
 * you for a chosen boss or activity, refreshed from the official Jagex
 * hiscores only while the panel is open.
 */
@Slf4j
@PluginDescriptor(
	name = "Noot's Rank Ladder",
	description = "Shows a live hiscores ladder of the players ranked just above and below you for any boss or activity",
	tags = {"hiscores", "rank", "ladder", "leaderboard", "boss", "tracker", "noots"}
)
public class RankLadderPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Provider<RankLadderPanel> panelProvider;

	@Inject
	private RankLadderPoller poller;

	private RankLadderPanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception
	{
		panel = panelProvider.get();
		// the singleton panel outlives disable/re-enable cycles, but the
		// poller clears its callback on shutDown; re-register every start
		poller.setRefreshCallback(panel::refresh);
		navButton = NavigationButton.builder()
			.tooltip("Noot's Rank Ladder")
			.icon(createIcon())
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		poller.shutDown();
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
	}

	private static BufferedImage createIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(30, 45, 70));
		g.fillRoundRect(0, 0, 16, 16, 5, 5);
		// a climbing arrow up the ladder
		g.setColor(new Color(120, 200, 255));
		g.fillPolygon(new int[]{8, 12, 10, 10, 6, 6, 4}, new int[]{2, 7, 7, 13, 13, 7, 7}, 7);
		g.dispose();
		return icon;
	}

	@Provides
	RankLadderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RankLadderConfig.class);
	}
}

