	private void restoreSelection()
	{
		String savedMode = configManager.getConfiguration(RankLadderConfig.GROUP, "selectedMode");
		if (savedMode != null)
		{
			try
			{
				RankLadderClient.HiscoreMode mode = RankLadderClient.HiscoreMode.valueOf(savedMode);
				modeCombo.setSelectedItem(mode);
				state.setSelectedMode(mode);
			}
			catch (IllegalArgumentException ignored)
			{
			}
		}
		String savedActivity = configManager.getConfiguration(RankLadderConfig.GROUP, "selectedActivity");
		if (savedActivity != null && !savedActivity.isEmpty())
		{
			activityCombo.addItem(savedActivity);
			activityCombo.setSelectedItem(savedActivity);
			state.setSelectedActivity(savedActivity);
		}
		else
		{
			activityCombo.setSelectedIndex(-1);
		}
	}

	private void selectionChanged()
	{
		if (updatingCombos)
		{
			return;
		}
		RankLadderClient.HiscoreMode mode = (RankLadderClient.HiscoreMode) modeCombo.getSelectedItem();
		String activity = (String) activityCombo.getSelectedItem();
		boolean modeChanged = mode != null && mode != state.getSelectedMode();
		boolean activityChanged = activity != null && !activity.equals(state.getSelectedActivity());
		if (!modeChanged && !activityChanged)
		{
			// re-picking the same entry must not wipe the session
			return;
		}
		if (modeChanged)
		{
			state.setSelectedMode(mode);
			configManager.setConfiguration(RankLadderConfig.GROUP, "selectedMode", mode.name());
		}
		if (activityChanged)
		{
			state.setSelectedActivity(activity);
			configManager.setConfiguration(RankLadderConfig.GROUP, "selectedActivity", activity);
		}
		state.setLadder(new ArrayList<>());
		state.setYourRank(0);
		state.setSessionStartRank(0);
		ladderView.reset();
		poller.pollNow();
	}

