	void startPolling()
	{
		poller.start();
	}

	void stopPolling()
	{
		poller.stop();
		ladderView.stopAnim();
	}

	public void refresh()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refresh);
			return;
		}

		refreshActivityCombo();

		String error = state.getError();
		errorLabel.setText(error == null ? "" : "<html><center>" + error + "</center></html>");
		errorLabel.setToolTipText(error);
		errorLabel.setForeground(state.isErrorFailure() ? SOFT_RED : AMBER);

		int rank = state.getYourRank();
		rankBig.setText(rank > 0 ? "#" + String.format("%,d", rank) : "-");
		int startRank = state.getSessionStartRank();
		if (rank > 0 && startRank > 0 && rank != startRank)
		{
			int climbed = startRank - rank;
			sessionLabel.setText((climbed > 0 ? "+" : "") + climbed + " this session");
			sessionLabel.setForeground(climbed > 0 ? GOOD : SOFT_RED);
		}
		else
		{
			sessionLabel.setText("your rank");
			sessionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}

		scoreLabel.setText(state.getYourScore() > 0 ? String.format("%,d", state.getYourScore()) : "-");

		// unit-less numbers: not every activity is a kill count
		long gap = gapToNextRank();
		gapLabel.setText(gap > 0 ? String.format("%,d", gap) : "-");

		double perHour = state.scorePerHour();
		paceLabel.setText(Double.isNaN(perHour) ? "collecting data..." : String.format("%.1f/hr", perHour));
		paceLabel.setForeground(Double.isNaN(perHour) ? ColorScheme.LIGHT_GRAY_COLOR : Color.WHITE);

		etaLabel.setText(gap > 0 && !Double.isNaN(perHour) && perHour > 0
			? "~" + formatHours(gap / perHour) : "-");

		RankLadderState.LadderEntry rankOne = state.getRankOne();
		if (rankOne == null)
		{
			rankOneLabel.setText("-");
		}
		else if (rank == 1)
		{
			rankOneLabel.setText(String.format("%,d, that's you", rankOne.getScore()));
		}
		else
		{
			long rankOneGap = rankOne.getScore() + 1 - state.getYourScore();
			String eta = !Double.isNaN(perHour) && perHour > 0 && rankOneGap > 0
				? " (~" + formatHours(rankOneGap / perHour) + ")" : "";
			rankOneLabel.setText(String.format("%,d%s", rankOne.getScore(), eta));
		}

		double rankPace = state.ranksPerDay();
		trendLabel.setText(Double.isNaN(rankPace) ? "-"
			: String.format("%+.1f ranks/day", rankPace));
		trendLabel.setForeground(Double.isNaN(rankPace) || rankPace == 0 ? Color.WHITE
			: rankPace > 0 ? GOOD : SOFT_RED);

		updatedLabel.setText(state.getLastUpdatedMs() > 0
			? new SimpleDateFormat("HH:mm:ss").format(new Date(state.getLastUpdatedMs())) : "-");

		ladderView.setData(state.getLadder(), rank);
	}

	private void refreshActivityCombo()
	{
		if (activityCombo.isPopupVisible())
		{
			// never rebuild the list under the user's open dropdown; the
			// next refresh reconciles it
			return;
		}
		List<String> names = state.getActivityNames();
		if (names.isEmpty())
		{
			return;
		}
		if (activityCombo.getItemCount() == names.size())
		{
			boolean same = true;
			for (int i = 0; i < names.size(); i++)
			{
				if (!Objects.equals(activityCombo.getItemAt(i), names.get(i)))
				{
					same = false;
					break;
				}
			}
			if (same)
			{
				return;
			}
		}
		updatingCombos = true;
		try
		{
			String selected = state.getSelectedActivity();
			activityCombo.removeAllItems();
			for (String name : names)
			{
				activityCombo.addItem(name);
			}
			if (selected != null && names.contains(selected))
			{
				activityCombo.setSelectedItem(selected);
			}
			else
			{
				activityCombo.setSelectedIndex(-1);
			}
		}
		finally
		{
			updatingCombos = false;
		}
	}

	private long gapToNextRank()
	{
		int rank = state.getYourRank();
		if (rank <= 1)
		{
			return 0;
		}
		for (RankLadderState.LadderEntry entry : state.getLadder())
		{
			if (entry.getRank() == rank - 1)
			{
				return entry.getScore() + 1 - state.getYourScore();
			}
		}
		return 0;
	}

	private static String formatHours(double hours)
	{
		long totalMinutes = Math.max(1, Math.round(hours * 60));
		if (totalMinutes < 60)
		{
			return totalMinutes + "m";
		}
		long h = totalMinutes / 60;
		if (h < 48)
		{
			return h + "h " + (totalMinutes % 60) + "m";
		}
		long days = Math.round(h / 24.0);
		if (days < 365)
		{
			return days + " days";
		}
		return "over a year";
	}

	private static String rowKey(String name)
	{
		return name.toLowerCase(Locale.ROOT);
	}

	/**
	 * The vertical ladder. Two-line rows: name and score, then how far
	 * ahead or behind you that player is. When a new snapshot reorders
	 * the ladder, rows slide to their new slots; passing someone pulses
	 * your row green.
	 */
	private class LadderView extends JPanel
	{
		private static final int ROW_H = 40;
		private static final int RAIL_X = 12;
		private static final int ANIM_MS = 550;
		private static final int FLASH_MS = 1400;

		private List<RankLadderState.LadderEntry> rows = new ArrayList<>();
		private Map<String, Integer> fromSlots = new HashMap<>();
		private long animStartMs;
		private boolean animating;
		private long flashUntilMs;
		private int lastRank;
		private int yourRank;
		private final Timer animTimer = new Timer(15, e -> onAnimTick());

		LadderView()
		{
			setOpaque(true);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
		}

		void stopAnim()
		{
			animating = false;
			flashUntilMs = 0;
			animTimer.stop();
		}

		void reset()
		{
			rows = new ArrayList<>();
			fromSlots.clear();
			animating = false;
			flashUntilMs = 0;
			lastRank = 0;
			animTimer.stop();
			revalidate();
			repaint();
		}

		void setData(List<RankLadderState.LadderEntry> newRows, int newYourRank)
		{
			if (lastRank > 0 && newYourRank > 0 && newYourRank < lastRank)
			{
				flashUntilMs = System.currentTimeMillis() + FLASH_MS;
			}
			if (newYourRank > 0)
			{
				lastRank = newYourRank;
			}
			yourRank = newYourRank;

			if (!sameOrder(newRows))
			{
				Map<String, Integer> old = new HashMap<>();
				for (int i = 0; i < rows.size(); i++)
				{
					old.put(rowKey(rows.get(i).getName()), i);
				}
				if (!old.isEmpty())
				{
					fromSlots = old;
					animStartMs = System.currentTimeMillis();
					animating = true;
				}
				rows = newRows;
				revalidate();
			}
			else
			{
				rows = newRows;
			}
			if ((animating || flashUntilMs > System.currentTimeMillis()) && !animTimer.isRunning())
			{
				animTimer.start();
			}
			repaint();
		}

		private boolean sameOrder(List<RankLadderState.LadderEntry> newRows)
		{
			if (newRows.size() != rows.size())
			{
				return false;
			}
			for (int i = 0; i < newRows.size(); i++)
			{
				if (!rowKey(newRows.get(i).getName()).equals(rowKey(rows.get(i).getName())))
				{
					return false;
				}
			}
			return true;
		}

		private void onAnimTick()
		{
			long now = System.currentTimeMillis();
			if (animating && now - animStartMs >= ANIM_MS)
			{
				animating = false;
				fromSlots.clear();
			}
			if (!animating && now >= flashUntilMs)
			{
				animTimer.stop();
			}
			repaint();
		}

		@Override
		public Dimension getPreferredSize()
		{
			// width is dictated by the panel; only the height matters
			int count = Math.max(2, rows.size());
			return new Dimension(140, count * ROW_H + 26);
		}

		@Override
		protected void paintComponent(Graphics g0)
		{
			super.paintComponent(g0);
			Graphics2D g = (Graphics2D) g0;
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			// pixel font stays sharp without text AA; sans draws flip it on
			setTextAA(g, false);

			int w = getWidth();
			int top = 20;

			if (rows.isEmpty())
			{
				g.setColor(WORSE);
				g.setFont(FONT_PIXEL);
				g.drawString("Pick a boss or activity above;", 10, 30);
				g.drawString("the ladder loads while this", 10, 46);
				g.drawString("panel is open.", 10, 62);
				return;
			}

			long now = System.currentTimeMillis();
			double progress = animating
				? Math.min(1, (now - animStartMs) / (double) ANIM_MS) : 1;
			double eased = easeInOut(progress);

			// direction hint: up the rail is toward rank 1
			g.setColor(RANK_NUM);
			g.setFont(FONT_PIXEL);
			g.fillPolygon(new int[]{RAIL_X - 4, RAIL_X + 4, RAIL_X}, new int[]{11, 11, 4}, 3);
			g.drawString("rank 1", RAIL_X + 9, 14);

			g.setColor(RAIL);
			g.setStroke(new BasicStroke(2f));
			g.drawLine(RAIL_X, top, RAIL_X, top + rows.size() * ROW_H - ROW_H / 2);

			// the rank column grows with the numbers (#76,194 is wide)
			FontMetrics rankFm = g.getFontMetrics(FONT_RANK);
			int maxRankW = 0;
			for (RankLadderState.LadderEntry row : rows)
			{
				maxRankW = Math.max(maxRankW,
					rankFm.stringWidth("#" + String.format("%,d", row.getRank())));
			}
			int nameX = RAIL_X + 12 + maxRankW + 7;

			for (int i = 0; i < rows.size(); i++)
			{
				RankLadderState.LadderEntry row = rows.get(i);
				Integer from = fromSlots.get(rowKey(row.getName()));
				double slot = from == null ? i : from + (i - from) * eased;
				float alpha = from == null && animating ? (float) eased : 1f;
				int y = top + (int) Math.round(slot * ROW_H);

				Composite saved = g.getComposite();
				if (alpha < 1f)
				{
					g.setComposite(AlphaComposite.SrcOver.derive(alpha));
				}
				paintRow(g, row, w, y, now, nameX);
				g.setComposite(saved);
			}
		}

		private void paintRow(Graphics2D g, RankLadderState.LadderEntry row, int w, int y, long now, int nameX)
		{
			int cy = y + 15;
			if (row.isYou())
			{
				int glow = 26;
				if (now < flashUntilMs)
				{
					// green pulse right after passing someone
					double remaining = (flashUntilMs - now) / (double) FLASH_MS;
					g.setColor(new Color(GOOD.getRed(), GOOD.getGreen(), GOOD.getBlue(),
						(int) (90 * remaining)));
					g.fillRoundRect(2, y - 2, w - 4, ROW_H - 4, 10, 10);
				}
				g.setColor(new Color(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), glow));
				g.fillRoundRect(2, y - 2, w - 4, ROW_H - 4, 10, 10);
				g.setColor(ACCENT);
				g.drawRoundRect(2, y - 2, w - 4, ROW_H - 4, 10, 10);
				g.fillOval(RAIL_X - 5, cy - 5, 10, 10);
			}
			else
			{
				g.setColor(RAIL);
				g.fillOval(RAIL_X - 3, cy - 3, 6, 6);
				g.setColor(new Color(255, 255, 255, 10));
				g.drawLine(RAIL_X + 12, y + ROW_H - 4, w - 4, y + ROW_H - 4);
			}

			// rank and name: the important bits, crisp sans with AA
			setTextAA(g, true);
			g.setFont(FONT_RANK);
			g.setColor(row.isYou() ? ACCENT : RANK_NUM);
			g.drawString("#" + String.format("%,d", row.getRank()), RAIL_X + 12, cy + 4);

			String score = String.format("%,d", row.getScore());
			int scoreW = g.getFontMetrics(FONT_PIXEL).stringWidth(score);

			g.setFont(row.isYou() ? FONT_NAME_BOLD : FONT_NAME);
			g.setColor(row.isYou() ? Color.WHITE : (row.getRank() < yourRank ? BETTER : WORSE));
			String name = clip(row.getName(), g.getFontMetrics(), w - nameX - scoreW - 10);
			g.drawString(name, nameX, cy + 4);

			// score and subtext: classic pixel font, sharp without AA
			setTextAA(g, false);
			g.setFont(FONT_PIXEL);
			g.drawString(score, w - scoreW - 4, cy + 4);

			// second line: this player's distance from you
			if (!row.isYou() && yourRank > 0)
			{
				long diff = row.getScore() - state.getYourScore();
				String sub;
				Color subColor = SUBTEXT;
				if (diff == 0)
				{
					sub = "tied with you";
					subColor = TIE;
				}
				else if (diff > 0)
				{
					sub = String.format("%,d ahead", diff);
				}
				else
				{
					sub = String.format("%,d behind", -diff);
				}
				g.setColor(subColor);
				g.drawString(sub, nameX, cy + 18);
			}
		}

		private void setTextAA(Graphics2D g, boolean on)
		{
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				on ? RenderingHints.VALUE_TEXT_ANTIALIAS_ON : RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		}

		private double easeInOut(double t)
		{
			return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
		}

		private String clip(String text, FontMetrics fm, int maxWidth)
		{
			if (fm.stringWidth(text) <= maxWidth)
			{
				return text;
			}
			String clipped = text;
			while (clipped.length() > 1 && fm.stringWidth(clipped + "..") > maxWidth)
			{
				clipped = clipped.substring(0, clipped.length() - 1);
			}
			return clipped + "..";
		}
	}
}

package com.liam.rankladder;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(RankLadderConfig.GROUP)
public interface RankLadderConfig extends Config
{
	String GROUP = "noots-rank-ladder";

	@ConfigItem(
		keyName = "playerName",
		name = "Player name",
		description = "The name to track on the hiscores (leave blank to use your logged-in character)",
		position = 0
	)
	default String playerName()
	{
		return "";
	}

	@Range(min = 30, max = 600)
	@ConfigItem(
		keyName = "pollSeconds",
		name = "Refresh every (s)",
		description = "How often to refresh the ladder while the panel is open",
		position = 1
	)
	default int pollSeconds()
	{
		return 60;
	}

	@Range(min = 3, max = 12)
	@ConfigItem(
		keyName = "ladderDepth",
		name = "Ladder depth",
		description = "How many players to show above and below you",
		position = 2
	)
	default int ladderDepth()
	{
		return 5;
	}
}
